namespace sv_76e7dabf3015471ca508805c77a6c84e.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@page "/catalog"
@using sv_76e7dabf3015471ca508805c77a6c84e.Services
@inject IProductService ProductService
@inject NavigationManager Navigation
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h1 class="mb-4">Product Catalog</h1>

<div class="catalog-layout">
    @* ───── Left Sidebar: Filters ───── *@
    <aside class="catalog-sidebar">
        <h5>Filters</h5>

        @* Category checkboxes *@
        <div class="mb-3">
            <label class="form-label fw-semibold">Category</label>
            @if (categories is not null)
            {
                @foreach (var cat in categories)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox" id="@($"cat-{cat}")"
                               checked="@selectedCategories.Contains(cat)"
                               @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                        <label class="form-check-label" for="@($"cat-{cat}")">@cat</label>
                    </div>
                }
            }
            else
            {
                <p class="text-muted small">Loading categories…</p>
            }
        </div>

        @* Price range *@
        <div class="mb-3">
            <label class="form-label fw-semibold">Price Range</label>
            <div class="d-flex gap-2">
                <input type="number" class="form-control form-control-sm" placeholder="Min"
                       @bind="minPrice" min="0" step="0.01" />
                <input type="number" class="form-control form-control-sm" placeholder="Max"
                       @bind="maxPrice" min="0" step="0.01" />
            </div>
        </div>

        @* In-stock toggle *@
        <div class="form-check mb-3">
            <input class="form-check-input" type="checkbox" id="inStockOnly" @bind="inStockOnly" />
            <label class="form-check-label" for="inStockOnly">In Stock Only</label>
        </div>

        @* Action buttons *@
        <div class="d-grid gap-2">
            <button class="btn btn-primary btn-sm" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    @* ───── Main Content ───── *@
    <section class="catalog-main">
        @if (errorMessage is not null)
        {
            <div class="alert alert-danger" role="alert">
                <strong>Error:</strong> @errorMessage
                <button class="btn btn-link p-0 ms-2" @onclick="RetryLoad">Retry</button>
            </div>
        }
        else if (isLoading)
        {
            <div class="d-flex justify-content-center align-items-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading…</span>
                </div>
                <span class="ms-3">Loading products…</span>
            </div>
        }
        else if (result is null || result.Items.Count == 0)
        {
            <div class="text-center py-5 text-muted">
                <h4>No products found</h4>
                <p>Try adjusting your filters or clearing them.</p>
            </div>
        }
        else
        {
            @* Toolbar *@
            <div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2">
                <div>
                    <label class="form-label mb-0 me-2 fw-semibold" for="sortSelect">Sort by:</label>
                    <select id="sortSelect" class="form-select form-select-sm d-inline-block w-auto"
                            @bind="sortBy" @bind:after="OnSortChanged">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A–Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>
                <span class="text-muted small">
                    Showing @ShowingStart–@ShowingEnd of @result.TotalCount products
                </span>
            </div>

            @* Product grid *@
            <div class="product-grid">
                @foreach (var product in result.Items)
                {
                    <div class="card product-card h-100" tabindex="0"
                         @onclick="() => OnProductClicked(product.Id)"
                         @onkeydown="e => { if (e.Key == \"Enter\") OnProductClicked(product.Id); }">
                        <div class="card-img-placeholder d-flex align-items-center justify-content-center bg-light"
                             role="img" aria-label="@product.Name">
                            <span class="text-muted small text-center px-2">@product.Name</span>
                        </div>
                        <div class="card-body d-flex flex-column">
                            <h6 class="card-title text-truncate" title="@product.Name">@product.Name</h6>
                            <p class="card-text fw-bold mb-1">@product.Price.ToString("C")</p>
                            <p class="card-text mb-1">
                                <span class="star-rating" aria-label="@($"{product.Rating:F1} out of 5 stars")">
                                    @RenderStars(product.Rating)
                                </span>
                            </p>
                            @if (!product.InStock)
                            {
                                <span class="badge bg-danger mb-2">Out of Stock</span>
                            }
                            <button class="btn btn-sm btn-success mt-auto"
                                    disabled="@(!product.InStock)"
                                    @onclick="() => AddToCart(product.Id)"
                                    @onclick:stopPropagation="true">
                                Add to Cart
                            </button>
                        </div>
                    </div>
                }
            </div>

            @* Pagination *@
            <nav aria-label="Product pagination" class="mt-4">
                <ul class="pagination justify-content-center flex-wrap">
                    <li class="page-item @(currentPage <= 1 ? "disabled" : "")">
                        <button class="page-link" @onclick="() => GoToPage(currentPage - 1)"
                                disabled="@(currentPage <= 1)">Previous</button>
                    </li>
                    @for (int i = 1; i <= TotalPages; i++)
                    {
                        var pageNum = i;
                        <li class="page-item @(pageNum == currentPage ? "active" : "")">
                            <button class="page-link" @onclick="() => GoToPage(pageNum)">@pageNum</button>
                        </li>
                    }
                    <li class="page-item @(currentPage >= TotalPages ? "disabled" : "")">
                        <button class="page-link" @onclick="() => GoToPage(currentPage + 1)"
                                disabled="@(currentPage >= TotalPages)">Next</button>
                    </li>
                </ul>
            </nav>
        }
    </section>
</div>

@code {
    private const int PageSize = 12;

    // Filter state
    private List<string>? categories;
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;

    // Results state
    private PagedResult<Product>? result;
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private bool isLoading = true;
    private string? errorMessage;

    // Computed helpers
    private int TotalPages => result is null || result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)result.TotalCount / PageSize);

    private int ShowingStart => result is null || result.Items.Count == 0
        ? 0
        : (result.Page - 1) * result.PageSize + 1;

    private int ShowingEnd => result is null
        ? 0
        : Math.Min(result.Page * result.PageSize, result.TotalCount);

    protected override async Task OnInitializedAsync()
    {
        await LoadInitialDataAsync();
    }

    private async Task LoadInitialDataAsync()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = SearchProductsAsync();

            categories = await categoriesTask;
            await productsTask;
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task SearchProductsAsync()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var filter = new ProductFilter(
                Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
                MinPrice: minPrice,
                MaxPrice: maxPrice,
                InStockOnly: inStockOnly
            );

            result = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await SearchProductsAsync();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        sortBy = "price_asc";
        await SearchProductsAsync();
    }

    private async Task OnSortChanged()
    {
        currentPage = 1;
        await SearchProductsAsync();
    }

    private async Task GoToPage(int page)
    {
        if (page < 1 || page > TotalPages) return;
        currentPage = page;
        await SearchProductsAsync();
    }

    private void OnProductClicked(int productId)
    {
        Navigation.NavigateTo($"/product/{productId}");
    }

    private void AddToCart(int productId)
    {
        // Placeholder for cart functionality
    }

    private async Task RetryLoad()
    {
        await LoadInitialDataAsync();
    }

    private static string RenderStars(double rating)
    {
        int fullStars = (int)Math.Round(rating);
        int emptyStars = 5 - fullStars;
        return new string('★', fullStars) + new string('☆', emptyStars);
    }
}

/* Catalog two-column layout */
.catalog-layout {
    display: flex;
    gap: 1.5rem;
}

.catalog-sidebar {
    flex: 0 0 25%;
    max-width: 25%;
    border-right: 1px solid #dee2e6;
    padding-right: 1.5rem;
}

.catalog-main {
    flex: 1 1 75%;
    min-width: 0;
}

/* Product grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1rem;
}

/* Product card */
.product-card {
    cursor: pointer;
    transition: box-shadow 0.2s, transform 0.15s;
}

.product-card:hover,
.product-card:focus-visible {
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.13);
    transform: translateY(-2px);
}

/* Placeholder image area */
.card-img-placeholder {
    height: 160px;
    border-bottom: 1px solid #eee;
    overflow: hidden;
}

/* Star rating */
.star-rating {
    color: #f5a623;
    letter-spacing: 1px;
    font-size: 1rem;
}

/* Responsive */
@media (max-width: 768px) {
    .catalog-layout {
        flex-direction: column;
    }

    .catalog-sidebar {
        flex: none;
        max-width: 100%;
        border-right: none;
        border-bottom: 1px solid #dee2e6;
        padding-right: 0;
        padding-bottom: 1rem;
        margin-bottom: 1rem;
    }
}

